[metadata] {"type": "create", "filePath": "/app/output/index.html", "content": "<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>Leap Studio — Your Reinvention and Experience Partner</title>
  <link rel="preconnect" href="https://fonts.googleapis.com" />
  <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin />
  <link href="https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500;600;700;800;900&display=swap" rel="stylesheet" />
  <style>
    /* ─── DESIGN TOKENS ─────────────────────────────────────────── */
    :root {
      --bg:          oklch(7% 0.004 265);
      --bg-surface:  oklch(11% 0.005 265);
      --bg-raised:   oklch(15% 0.006 265);
      --bg-hover:    oklch(18% 0.007 265);
      --border:      oklch(22% 0.006 265);
      --border-subtle: oklch(16% 0.005 265);

      --text-primary:   oklch(97% 0.003 265);
      --text-secondary: oklch(65% 0.010 265);
      --text-muted:     oklch(42% 0.008 265);

      --accent-blue:    oklch(62% 0.22 255);
      --accent-blue-dim: oklch(55% 0.18 255);
      --accent-amber:   oklch(78% 0.18 72);
      --accent-glow:    oklch(62% 0.22 255 / 0.15);

      --radius-sm:  4px;
      --radius-md:  8px;
      --radius-lg:  16px;
      --radius-xl:  24px;

      --transition: 0.3s cubic-bezier(0.4, 0, 0.2, 1);
      --transition-fast: 0.15s cubic-bezier(0.4, 0, 0.2, 1);

      --font: 'Inter', -apple-system, BlinkMacSystemFont, sans-serif;
    }

    /* ─── RESET ─────────────────────────────────────────────────── */
    *, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }
    html { scroll-behavior: smooth; }
    body {
      font-family: var(--font);
      background: var(--bg);
      color: var(--text-primary);
      line-height: 1.6;
      overflow-x: hidden;
      -webkit-font-smoothing: antialiased;
    }
    a { color: inherit; text-decoration: none; }
    button { font-family: var(--font); cursor: pointer; border: none; background: none; }
    img { display: block; max-width: 100%; }
    ul { list-style: none; }

    /* ─── UTILITY ────────────────────────────────────────────────── */
    .container { max-width: 1280px; margin: 0 auto; padding: 0 32px; }
    .sr-only { position: absolute; width: 1px; height: 1px; overflow: hidden; clip: rect(0,0,0,0); white-space: nowrap; }

    /* ─── NOISE OVERLAY ──────────────────────────────────────────── */
    body::before {
      content: '';
      position: fixed;
      inset: 0;
      background-image: url("data:image/svg+xml,%3Csvg viewBox='0 0 256 256' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='n'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='0.9' numOctaves='4' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23n)' opacity='0.04'/%3E%3C/svg%3E");
      pointer-events: none;
      z-index: 9999;
      opacity: 0.4;
    }

    /* ─── NAVIGATION ─────────────────────────────────────────────── */
    .nav {
      position: fixed;
      top: 0;
      left: 0;
      right: 0;
      z-index: 100;
      background: oklch(7% 0.004 265 / 0.9);
      backdrop-filter: blur(20px) saturate(1.5);
      border-bottom: 1px solid var(--border-subtle);
      transition: var(--transition);
    }
    .nav-inner {
      display: flex;
      align-items: center;
      justify-content: space-between;
      height: 68px;
    }
    .nav-logo {
      font-size: 1.25rem;
      font-weight: 800;
      letter-spacing: -0.03em;
      color: var(--text-primary);
      display: flex;
      align-items: center;
      gap: 8px;
    }
    .nav-logo-mark {
      width: 28px;
      height: 28px;
      background: var(--accent-blue);
      border-radius: 6px;
      display: flex;
      align-items: center;
      justify-content: center;
      font-size: 0.75rem;
      font-weight: 900;
      color: white;
    }
    .nav-links {
      display: flex;
      align-items: center;
      gap: 2px;
    }
    .nav-links a {
      font-size: 0.875rem;
      font-weight: 500;
      color: var(--text-secondary);
      padding: 8px 14px;
      border-radius: var(--radius-md);
      transition: var(--transition-fast);
    }
    .nav-links a:hover { color: var(--text-primary); background: var(--bg-surface); }
    .nav-links .nav-cta {
      color: var(--text-primary);
      background: var(--bg-surface);
      border: 1px solid var(--border);
      margin-left: 8px;
    }
    .nav-links .nav-cta:hover { border-color: var(--accent-blue); color: var(--accent-blue); background: var(--accent-glow); }

    .nav-right {
      display: flex;
      align-items: center;
      gap: 12px;
    }

    /* Language selector */
    .lang-selector {
      position: relative;
    }
    .lang-btn {
      display: flex;
      align-items: center;
      gap: 6px;
      font-size: 0.8125rem;
      font-weight: 500;
      color: var(--text-secondary);
      padding: 6px 12px;
      border-radius: var(--radius-md);
      border: 1px solid var(--border-subtle);
      background: transparent;
      transition: var(--transition-fast);
    }
    .lang-btn:hover { color: var(--text-primary); border-color: var(--border); }
    .lang-btn svg { transition: transform var(--transition-fast); }
    .lang-btn.open svg { transform: rotate(180deg); }
    .lang-dropdown {
      position: absolute;
      top: calc(100% + 8px);
      right: 0;
      min-width: 160px;
      background: var(--bg-surface);
      border: 1px solid var(--border);
      border-radius: var(--radius-lg);
      padding: 6px;
      opacity: 0;
      visibility: hidden;
      transform: translateY(-8px);
      transition: var(--transition-fast);
      box-shadow: 0 20px 40px oklch(0% 0 0 / 0.5);
    }
    .lang-dropdown.open { opacity: 1; visibility: visible; transform: translateY(0); }
    .lang-dropdown button {
      display: block;
      width: 100%;
      text-align: left;
      padding: 8px 14px;
      font-size: 0.875rem;
      color: var(--text-secondary);
      border-radius: var(--radius-md);
      transition: var(--transition-fast);
    }
    .lang-dropdown button:hover { color: var(--text-primary); background: var(--bg-raised); }

    /* Mobile nav toggle */
    .nav-hamburger {
      display: none;
      flex-direction: column;
      gap: 5px;
      padding: 8px;
      border-radius: var(--radius-md);
      background: transparent;
      border: 1px solid var(--border);
    }
    .nav-hamburger span {
      display: block;
      width: 20px;
      height: 2px;
      background: var(--text-primary);
      border-radius: 2px;
      transition: var(--transition-fast);
    }

    /* Mobile nav drawer */
    .nav-mobile {
      display: none;
      position: fixed;
      inset: 0;
      top: 68px;
      background: var(--bg);
      z-index: 99;
      padding: 32px;
      flex-direction: column;
      gap: 8px;
      transform: translateX(100%);
      transition: transform var(--transition);
    }
    .nav-mobile.open { transform: translateX(0); }
    .nav-mobile a {
      font-size: 1.25rem;
      font-weight: 600;
      color: var(--text-secondary);
      padding: 14px 0;
      border-bottom: 1px solid var(--border-subtle);
      display: block;
    }
    .nav-mobile a:hover { color: var(--text-primary); }

    /* ─── HERO ────────────────────────────────────────────────────── */
    .hero {
      padding-top: 68px;
      min-height: 100vh;
      position: relative;
      overflow: hidden;
      display: flex;
      flex-direction: column;
    }
    .hero-carousel {
      flex: 1;
      position: relative;
    }
    .hero-slide {
      position: absolute;
      inset: 0;
      display: flex;
      flex-direction: column;
      justify-content: flex-end;
      padding: 80px 0;
      opacity: 0;
      transform: translateX(40px);
      transition: opacity 0.7s cubic-bezier(0.4, 0, 0.2, 1),
                  transform 0.7s cubic-bezier(0.4, 0, 0.2, 1);
      pointer-events: none;
    }
    .hero-slide.active {
      opacity: 1;
      transform: translateX(0);
      pointer-events: auto;
    }
    .hero-slide.exit {
      opacity: 0;
      transform: translateX(-40px);
    }
    .hero-bg {
      position: absolute;
      inset: 0;
      z-index: 0;
    }
    .hero-bg-img {
      width: 100%;
      height: 100%;
      object-fit: cover;
      opacity: 0.18;
    }
    .hero-bg-gradient {
      position: absolute;
      inset: 0;
      background: linear-gradient(
        to bottom,
        var(--bg) 0%,
        oklch(7% 0.004 265 / 0.2) 40%,
        oklch(7% 0.004 265 / 0.8) 75%,
        var(--bg) 100%
      );
    }
    .hero-content {
      position: relative;
      z-index: 1;
    }
    .hero-eyebrow {
      font-size: 0.75rem;
      font-weight: 600;
      letter-spacing: 0.12em;
      text-transform: uppercase;
      color: var(--accent-blue);
      margin-bottom: 20px;
    }
    .hero-title {
      font-size: clamp(2.5rem, 5vw, 4.5rem);
      font-weight: 800;
      letter-spacing: -0.03em;
      line-height: 1.05;
      max-width: 820px;
      margin-bottom: 24px;
      color: var(--text-primary);
    }
    .hero-body {
      font-size: 1.125rem;
      color: var(--text-secondary);
      max-width: 520px;
      margin-bottom: 36px;
      line-height: 1.7;
    }
    .btn {
      display: inline-flex;
      align-items: center;
      gap: 8px;
      padding: 14px 28px;
      font-size: 0.9375rem;
      font-weight: 600;
      border-radius: var(--radius-md);
      transition: var(--transition-fast);
      cursor: pointer;
    }
    .btn-primary {
      background: var(--text-primary);
      color: var(--bg);
    }
    .btn-primary:hover {
      background: oklch(90% 0.003 265);
      transform: translateY(-1px);
    }
    .btn-outline {
      background: transparent;
      color: var(--text-primary);
      border: 1px solid var(--border);
    }
    .btn-outline:hover {
      border-color: var(--accent-blue);
      color: var(--accent-blue);
      background: var(--accent-glow);
    }
    .btn-blue {
      background: var(--accent-blue);
      color: white;
    }
    .btn-blue:hover {
      background: var(--accent-blue-dim);
      transform: translateY(-1px);
    }
    .btn svg { flex-shrink: 0; }

    /* Hero controls */
    .hero-controls {
      position: absolute;
      bottom: 48px;
      left: 0;
      right: 0;
      z-index: 10;
    }
    .hero-controls-inner {
      display: flex;
      align-items: center;
      justify-content: space-between;
    }
    .hero-dots {
      display: flex;
      align-items: center;
      gap: 8px;
    }
    .hero-dot {
      width: 6px;
      height: 6px;
      border-radius: 50%;
      background: var(--border);
      transition: var(--transition-fast);
      cursor: pointer;
      border: none;
    }
    .hero-dot.active {
      width: 24px;
      border-radius: 3px;
      background: var(--accent-blue);
    }
    .hero-arrows {
      display: flex;
      gap: 8px;
    }
    .hero-arrow {
      width: 44px;
      height: 44px;
      border-radius: 50%;
      border: 1px solid var(--border);
      background: var(--bg-surface);
      color: var(--text-primary);
      display: flex;
      align-items: center;
      justify-content: center;
      transition: var(--transition-fast);
    }
    .hero-arrow:hover { border-color: var(--accent-blue); color: var(--accent-blue); background: var(--accent-glow); }

    /* Hero progress bar */
    .hero-progress {
      position: absolute;
      bottom: 0;
      left: 0;
      height: 2px;
      background: var(--accent-blue);
      width: 0%;
      transition: width 0.1s linear;
    }

    /* ─── SECTION COMMON ─────────────────────────────────────────── */
    section { padding: 100px 0; }
    .section-eyebrow {
      font-size: 0.75rem;
      font-weight: 600;
      letter-spacing: 0.12em;
      text-transform: uppercase;
      color: var(--accent-blue);
      margin-bottom: 16px;
    }
    .section-title {
      font-size: clamp(2rem, 3.5vw, 3rem);
      font-weight: 800;
      letter-spacing: -0.03em;
      line-height: 1.1;
      margin-bottom: 16px;
    }
    .section-subtitle {
      font-size: 1.0625rem;
      color: var(--text-secondary);
      max-width: 560px;
      line-height: 1.7;
      margin-bottom: 56px;
    }
    .section-header {
      display: flex;
      align-items: flex-end;
      justify-content: space-between;
      gap: 32px;
      margin-bottom: 56px;
    }
    .section-header-left { flex: 1; }

    /* ─── TEAM CAROUSEL ───────────────────────────────────────────── */
    .team-section { background: var(--bg); }
    .team-header { margin-bottom: 0; }
    .region-tabs {
      display: flex;
      gap: 4px;
      margin-bottom: 40px;
      border-bottom: 1px solid var(--border-subtle);
      padding-bottom: 0;
    }
    .region-tab {
      font-size: 0.9375rem;
      font-weight: 600;
      color: var(--text-muted);
      padding: 12px 20px;
      border-radius: 0;
      border-bottom: 2px solid transparent;
      margin-bottom: -1px;
      transition: var(--transition-fast);
      background: transparent;
    }
    .region-tab:hover { color: var(--text-secondary); }
    .region-tab.active {
      color: var(--text-primary);
      border-bottom-color: var(--accent-blue);
    }

    .team-grid {
      display: none;
      grid-template-columns: repeat(auto-fill, minmax(280px, 1fr));
      gap: 20px;
    }
    .team-grid.active { display: grid; }

    .team-card {
      background: var(--bg-surface);
      border: 1px solid var(--border-subtle);
      border-radius: var(--radius-xl);
      overflow: hidden;
      transition: var(--transition);
    }
    .team-card:hover {
      border-color: var(--border);
      transform: translateY(-4px);
      box-shadow: 0 24px 48px oklch(0% 0 0 / 0.4);
    }
    .team-photo {
      width: 100%;
      aspect-ratio: 4/3;
      object-fit: cover;
      background: var(--bg-raised);
      position: relative;
      overflow: hidden;
    }
    .team-photo-placeholder {
      width: 100%;
      aspect-ratio: 4/3;
      background: var(--bg-raised);
      display: flex;
      align-items: center;
      justify-content: center;
      position: relative;
      overflow: hidden;
    }
    .team-photo-placeholder::before {
      content: '';
      position: absolute;
      inset: 0;
      background: linear-gradient(135deg, var(--bg-raised) 0%, var(--bg-hover) 100%);
    }
    .team-avatar {
      position: relative;
      width: 72px;
      height: 72px;
      border-radius: 50%;
      background: var(--border);
      display: flex;
      align-items: center;
      justify-content: center;
      font-size: 1.5rem;
      font-weight: 700;
      color: var(--text-muted);
    }
    .team-card-body {
      padding: 24px;
    }
    .team-quote {
      font-size: 0.9375rem;
      color: var(--text-secondary);
      line-height: 1.7;
      margin-bottom: 20px;
      font-style: italic;
    }
    .team-quote::before { content: '"'; }
    .team-quote::after { content: '"'; }
    .team-name {
      font-size: 1rem;
      font-weight: 700;
      margin-bottom: 4px;
    }
    .team-role {
      font-size: 0.8125rem;
      color: var(--text-muted);
      margin-bottom: 4px;
    }
    .team-office {
      font-size: 0.8125rem;
      color: var(--accent-blue);
      margin-bottom: 20px;
    }
    .team-cta {
      font-size: 0.8125rem;
      font-weight: 600;
      color: var(--text-secondary);
      display: flex;
      align-items: center;
      gap: 6px;
      transition: var(--transition-fast);
    }
    .team-cta:hover { color: var(--accent-blue); }
    .team-cta svg { transition: transform var(--transition-fast); }
    .team-cta:hover svg { transform: translateX(3px); }

    /* ─── WORK SHOWCASE ───────────────────────────────────────────── */
    .work-section { background: var(--bg-surface); }
    .work-carousel-wrap {
      position: relative;
      overflow: hidden;
    }
    .work-carousel-track {
      display: flex;
      gap: 20px;
      overflow-x: auto;
      scroll-snap-type: x mandatory;
      scroll-behavior: smooth;
      -webkit-overflow-scrolling: touch;
      padding-bottom: 16px;
      cursor: grab;
    }
    .work-carousel-track::-webkit-scrollbar { height: 4px; }
    .work-carousel-track::-webkit-scrollbar-track { background: var(--border-subtle); border-radius: 2px; }
    .work-carousel-track::-webkit-scrollbar-thumb { background: var(--border); border-radius: 2px; }
    .work-carousel-track:active { cursor: grabbing; }

    .work-card {
      flex: 0 0 380px;
      scroll-snap-align: start;
      background: var(--bg);
      border: 1px solid var(--border-subtle);
      border-radius: var(--radius-xl);
      overflow: hidden;
      transition: var(--transition);
    }
    .work-card:hover {
      border-color: var(--border);
      box-shadow: 0 24px 48px oklch(0% 0 0 / 0.4);
    }
    .work-thumb {
      width: 100%;
      aspect-ratio: 16/10;
      background: var(--bg-raised);
      position: relative;
      overflow: hidden;
    }
    .work-thumb-pattern {
      position: absolute;
      inset: 0;
      display: flex;
      align-items: center;
      justify-content: center;
    }
    .work-thumb-gradient {
      position: absolute;
      inset: 0;
    }
    .work-card-body { padding: 28px; }
    .work-client {
      font-size: 0.75rem;
      font-weight: 600;
      letter-spacing: 0.1em;
      text-transform: uppercase;
      color: var(--text-muted);
      margin-bottom: 10px;
    }
    .work-title {
      font-size: 1.125rem;
      font-weight: 700;
      letter-spacing: -0.02em;
      line-height: 1.3;
      margin-bottom: 14px;
    }
    .work-quote {
      font-size: 0.875rem;
      color: var(--text-muted);
      line-height: 1.6;
      margin-bottom: 20px;
    }
    .work-link {
      font-size: 0.875rem;
      font-weight: 600;
      color: var(--accent-blue);
      display: flex;
      align-items: center;
      gap: 6px;
      transition: var(--transition-fast);
    }
    .work-link:hover { gap: 10px; }
    .work-link svg { transition: transform var(--transition-fast); }
    .work-link:hover svg { transform: translateX(3px); }

    .work-nav {
      display: flex;
      justify-content: flex-end;
      gap: 8px;
      margin-top: 24px;
    }
    .work-arrow {
      width: 44px;
      height: 44px;
      border-radius: 50%;
      border: 1px solid var(--border);
      background: var(--bg-surface);
      color: var(--text-primary);
      display: flex;
      align-items: center;
      justify-content: center;
      transition: var(--transition-fast);
    }
    .work-arrow:hover { border-color: var(--accent-blue); color: var(--accent-blue); background: var(--accent-glow); }

    /* ─── CTA BANNER ─────────────────────────────────────────────── */
    .cta-banner {
      background: linear-gradient(135deg, oklch(18% 0.04 255) 0%, oklch(13% 0.02 255) 100%);
      border-top: 1px solid var(--border-subtle);
      border-bottom: 1px solid var(--border-subtle);
      padding: 80px 0;
    }
    .cta-banner-inner {
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 48px;
    }
    .cta-banner-title {
      font-size: clamp(2rem, 3.5vw, 2.75rem);
      font-weight: 800;
      letter-spacing: -0.03em;
      margin-bottom: 16px;
    }
    .cta-banner-body {
      font-size: 1rem;
      color: var(--text-secondary);
      max-width: 560px;
      line-height: 1.7;
    }

    /* ─── HOW WE WORK ─────────────────────────────────────────────── */
    .how-section { background: var(--bg); }
    .how-inner {
      display: grid;
      grid-template-columns: 1fr 1fr;
      gap: 80px;
      align-items: center;
    }
    .how-visual {
      aspect-ratio: 1;
      background: var(--bg-surface);
      border: 1px solid var(--border-subtle);
      border-radius: var(--radius-xl);
      overflow: hidden;
      position: relative;
      display: flex;
      align-items: center;
      justify-content: center;
    }
    .how-visual-rings {
      position: relative;
      width: 240px;
      height: 240px;
    }
    .ring {
      position: absolute;
      border-radius: 50%;
      border: 1px solid var(--border);
    }
    .ring-1 { inset: 0; border-color: oklch(62% 0.22 255 / 0.3); }
    .ring-2 { inset: 30px; border-color: oklch(62% 0.22 255 / 0.2); }
    .ring-3 { inset: 60px; border-color: oklch(62% 0.22 255 / 0.15); }
    .ring-core {
      position: absolute;
      inset: 90px;
      background: var(--accent-blue);
      border-radius: 50%;
      display: flex;
      align-items: center;
      justify-content: center;
      font-size: 1.5rem;
      box-shadow: 0 0 60px oklch(62% 0.22 255 / 0.4);
    }
    .how-text .section-title { margin-bottom: 24px; }
    .how-body {
      font-size: 1.0625rem;
      color: var(--text-secondary);
      line-height: 1.75;
      margin-bottom: 36px;
    }

    /* ─── INSIGHTS ────────────────────────────────────────────────── */
    .insights-section { background: var(--bg-surface); }
    .insights-grid {
      display: grid;
      grid-template-columns: repeat(4, 1fr);
      gap: 16px;
    }
    .insight-card {
      background: var(--bg);
      border: 1px solid var(--border-subtle);
      border-radius: var(--radius-lg);
      overflow: hidden;
      transition: var(--transition);
      display: flex;
      flex-direction: column;
    }
    .insight-card:hover {
      border-color: var(--border);
      transform: translateY(-4px);
      box-shadow: 0 16px 32px oklch(0% 0 0 / 0.4);
    }
    .insight-thumb {
      aspect-ratio: 16/9;
      background: var(--bg-raised);
      position: relative;
      overflow: hidden;
      flex-shrink: 0;
    }
    .insight-thumb-inner {
      position: absolute;
      inset: 0;
      display: flex;
      align-items: center;
      justify-content: center;
      font-size: 1.5rem;
    }
    .insight-body { padding: 20px; flex: 1; display: flex; flex-direction: column; }
    .insight-type {
      font-size: 0.7rem;
      font-weight: 700;
      letter-spacing: 0.12em;
      text-transform: uppercase;
      color: var(--accent-blue);
      margin-bottom: 8px;
    }
    .insight-title {
      font-size: 0.9375rem;
      font-weight: 700;
      line-height: 1.35;
      margin-bottom: 16px;
      flex: 1;
    }
    .insight-cta {
      font-size: 0.8125rem;
      font-weight: 600;
      color: var(--text-muted);
      display: flex;
      align-items: center;
      gap: 6px;
      transition: var(--transition-fast);
    }
    .insight-cta:hover { color: var(--accent-blue); }
    .insight-cta svg { transition: transform var(--transition-fast); }
    .insight-cta:hover svg { transform: translateX(3px); }

    /* ─── PRINCIPLES ──────────────────────────────────────────────── */
    .principles-section { background: var(--bg); }
    .principles-grid {
      display: grid;
      grid-template-columns: repeat(2, 1fr);
      gap: 1px;
      background: var(--border-subtle);
      border: 1px solid var(--border-subtle);
      border-radius: var(--radius-xl);
      overflow: hidden;
    }
    .principle-card {
      background: var(--bg);
      padding: 48px;
      transition: var(--transition-fast);
    }
    .principle-card:hover { background: var(--bg-surface); }
    .principle-num {
      font-size: 3rem;
      font-weight: 900;
      color: var(--border);
      letter-spacing: -0.04em;
      line-height: 1;
      margin-bottom: 24px;
    }
    .principle-title {
      font-size: 1.25rem;
      font-weight: 700;
      letter-spacing: -0.02em;
      margin-bottom: 14px;
    }
    .principle-body {
      font-size: 0.9375rem;
      color: var(--text-secondary);
      line-height: 1.7;
    }

    /* ─── FOOTER ──────────────────────────────────────────────────── */
    .footer {
      background: var(--bg-surface);
      border-top: 1px solid var(--border-subtle);
    }
    .footer-ctas {
      display: grid;
      grid-template-columns: 1fr 1fr;
      border-bottom: 1px solid var(--border-subtle);
    }
    .footer-cta-block {
      padding: 56px 48px;
      border-right: 1px solid var(--border-subtle);
